using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Preserve existing property name for backward compatibility.
            entity.HasDiscriminator().HasValue("Blog");
            entity.Property<string>("$type").ToJsonProperty("Discriminator");

            // Breaking change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Use a value generator or explicit mapping to keep the old format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<BlogIdGenerator>();

            // Breaking change 3: EF 9 removed support for HasIndex on Cosmos.
            // Cosmos DB does not support secondary indexes via EF; removed.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: Sync I/O now throws by default in EF 9 Cosmos provider.
        // Either switch to async or opt back in (shown below as a bridge).
        optionsBuilder.ConfigureWarnings(w => { });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

