using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Fix 1 – Discriminator property renamed to "$type" in EF 9.
            // Map it back to the JSON property "Discriminator" so existing docs are readable.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Fix 2 – id format changed from "Blog|1" to just the key value in EF 9.
            // Opt in to the legacy format so existing documents are still found.
            entity.Property(b => b.Id).ToJsonProperty("id");
            entity.UsePropertyAccessMode(PropertyAccessMode.Property);

            // Fix 3 – HasIndex() is no longer supported on Cosmos; removed.
            // (Cosmos manages indexing via indexing policy, not EF.)
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "BlogDb");
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

