using Microsoft.EntityFrameworkCore;
using System.Threading.Tasks;

class SyncJob
{
    // Breaking change 4 fix: EF 9 Cosmos provider no longer supports synchronous I/O.
    // Converted to async to avoid InvalidOperationException at runtime.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

